require_once __DIR__ . '/../../includes/admin_auth.php'; require_admin(); $courseStatement=$pdo->prepare('SELECT id,title FROM courses ORDER BY title');$courseStatement->execute();$courses=$courseStatement->fetchAll();$errors=[];
if(is_post_request()){$courseId=valid_id($_POST['course_id']??null);$title=post_string('module_title',180);$description=post_string('module_description',5000);$order=filter_var($_POST['module_order']??null,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);$status=isset($_POST['status'])?1:0;if(!verify_csrf_token($_POST['csrf_token']??null))$errors[]='Your form session expired. Please try again.';if($courseId===null||!in_array($courseId,array_map('intval',array_column($courses,'id')),true))$errors[]='Please select a valid course.';if($title==='')$errors[]='Module title is required.';if($description==='')$errors[]='Module description is required.';if($order===false)$errors[]='Module order must be a positive number.';if(!$errors){$insert=$pdo->prepare('INSERT INTO syllabus(course_id,module_title,module_description,module_order,status) VALUES(:course_id,:module_title,:module_description,:module_order,:status)');$insert->execute(['course_id'=>$courseId,'module_title'=>$title,'module_description'=>$description,'module_order'=>$order,'status'=>$status]);redirect('index.php');}}
admin_header('Add Syllabus Module','syllabus/index.php');?><div class="card table-card"><div class="card-body p-4"><form method="post"><input type="hidden" name="csrf_token" value="<?=e(csrf_token())?>"><?php if($errors):?><div class="alert alert-danger"><ul class="mb-0"><?php foreach($errors as $error):?><li><?=e($error)?></li><?php endforeach;?></ul></div><?php endif;?><div class="row g-3"><div class="col-md-7"><label class="form-label">Course *</label><select class="form-select" name="course_id" required><option value="">Select course</option><?php foreach($courses as $course):?><option value="<?=e($course['id'])?>" <?=((int)($_POST['course_id']??0)===(int)$course['id'])?'selected':''?>><?=e($course['title'])?></option><?php endforeach;?></select></div><div class="col-md-5"><label class="form-label">Module Order *</label><input class="form-control" type="number" min="1" name="module_order" value="<?=old('module_order','1')?>" required></div><div class="col-12"><label class="form-label">Module Title *</label><input class="form-control" name="module_title" value="<?=old('module_title')?>" required></div><div class="col-12"><label class="form-label">Module Description *</label><textarea class="form-control" name="module_description" rows="6" required><?=old('module_description')?></textarea></div><div class="col-12"><div class="form-check"><input class="form-check-input" type="checkbox" name="status" id="status" checked><label class="form-check-label" for="status">Active</label></div></div></div><div class="mt-4"><button class="btn btn-primary" type="submit">Save Module</button><a class="btn btn-outline-secondary ms-2" href="index.php">Cancel</a></div></form></div></div><?php admin_footer();?>
